OPE_WORKSPACE_ID : Your workspace ID. See Workspaces and regions . 



 Save the code below as livetranslate_client.py , run python livetranslate_client.py , and speak into the microphone. 


 The example uses qwen3.8-livetranslate-flash-realtime to translate microphone input into English, print the text, and play the translated speech in real time. Input is mono, 16-bit, 16000 Hz PCM; playback is mono, 16-bit, 24000 Hz PCM. Press Ctrl+C to stop recording. The example sends session.finish , receives and plays the remaining results, and closes the connection after session.finished . Use headphones to keep translated speech from being recorded again. 
 import base64
import json
import os
import signal
import threading
import time

import pyaudio
import websocket

model = "qwen3.8-livetranslate-flash-realtime"
workspace_id = os.environ["DASHSCOPE_WORKSPACE_ID"]
api_key = os.environ["DASHSCOPE_API_KEY"]
url = (
 f"wss://{workspace_id}.cn-beijing.maas.aliyuncs.com"
 f"/api-ws/v1/realtime?model={model}"
)
stop_recording = False
send_errors = []
ws = None
audio = None
input_stream = None
output_stream = None
sender = None
previous_sigint_handler = None

def receive():
 event = json.loads(ws.recv())
 if event.get("type") == "error" or event.get("code"):
 raise RuntimeError(event)
 return event

def stop_input(signum, frame):
 global stop_recording
 stop_recording = True

def send_audio():
 try:
 while not stop_recording:
 chunk = input_stream.read(1600)
 ws.send(json.dumps({
 "type": "input_audio_buffer.append",
 "audio": base64.b64encode(chunk).decode("ascii"),
 }))
 except Exception as error:
 send_errors.append(error)
 finally:
 try:
 ws.send(json.dumps({"type": "session.finish"}))
 except Exception as error:
 send_errors.append(error)
 ws.close()

def receive_translation():
 while True:
 event = receive()
 event_type = event.get("type")
 if event_type in ("response.text.delta", "response.audio_transcript.delta"):
 print(event["delta"], end="", flush=True)
 elif event_type == "response.audio.delta":
 output_stream.write(base64.b64decode(event["delta"]))
 elif event_type == "response.done":
 if event["response"]["status"] != "completed":
 raise RuntimeError(event["response"])
 print()
 elif event_type == "session.finished":
 return

try:
 ws = websocket.create_connection(
 url, header={"Authorization": f"Bearer {api_key}"}, timeout=30
 )
 while receive().get("type") != "session.created":
 pass
 ws.send(json.dumps({
 "type": "session.update",
 "session": {
 "output_modalities": ["text", "audio"],
 "translation": {"language": "en"},
 },
 }))
 while receive().get("type") != "session.updated":
 pass
 audio = pyaudio.PyAudio()
 input_stream = audio.open(
 format=pyaudio.paInt16, channels=1, rate=16000,
 input=True, frames_per_buffer=1600,
 )
 output_stream = audio.open(
 format=pyaudio.paInt16, channels=1, rate=24000, output=True,
 )
 print("Start speaking. Press Ctrl+C to stop recording and wait for the remaining translation.")
 previous_sigint_handler = signal.signal(signal.SIGINT, stop_input)
 sender = threading.Thread(target=send_audio, daemon=True)
 sender.start()
 receive_translation()
 stop_recording = True
 sender.join()
 if send_errors:
 raise send_errors[0]
except Exception:
 if send_errors:
 raise send_errors[0]
 raise
finally:
 stop_recording = True
 if ws is not None:
 ws.close()
 if sender is not None:
 sender.join()
 for stream in (input_stream, output_stream):
 if stream is not None:
 stream.stop_stream()
 stream.close()
 if audio is not None:
 audio.terminate()
 if previous_sigint_handler is not None:
 signal.signal(signal.SIGINT, previous_sigint_handler)

